    /**
     * Creates an SVG icon node with custom color and scale.
     */
    public static SVGPath createIcon(String pathData, String hexColor, double scale) {
        SVGPath svg = new SVGPath();
        svg.setContent(pathData);
        svg.setFill(Color.web(hexColor));
        svg.setScaleX(scale);
        svg.setScaleY(scale);
        return svg;
    }
